inputs.value:
@{if(
    empty(
        body('List_rows_from_selected_environment:_Conversation_Transcripts')?['@Microsoft.Dynamics.CRM.fetchxmlpagingcookie']
    ),
    '',
    replace(
        replace(
            replace(
                decodeUriComponent(
                    decodeUriComponent(
                        first(
                            split(
                                last(
                                    split(
                                        body('List_rows_from_selected_environment:_Conversation_Transcripts')?['@Microsoft.Dynamics.CRM.fetchxmlpagingcookie'],
                                        'pagingcookie="'
                                    )
                                ),
                                '" '
                            )
                        )
                    )
                ),
                '<', '&lt;'
            ),
            '>', '&gt;'
        ),
        '"', '&quot;'
    )
)
}
